#pragma once
static void testPluginRecovery(const juce::File& root){
 auto dir=root.getChildFile("plugin-recovery");dir.createDirectory();Session s(dir);s.importAudio(root.getChildFile("source.wav"),0,0);
 juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/editor/StudioTestGain_artefacts/Release/VST3/Studio Test Gain.vst3").getFullPathName());require(types.size()==1,"Recovery fixture scan failed");s.engine.getPluginManager().initialise();s.engine.getPluginManager().knownPluginList.addType(*types[0]);
 auto plugin=s.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*types[0]);auto* external=dynamic_cast<te::ExternalPlugin*>(plugin.get());require(external!=nullptr,"Recovery creation failed");s.trackAt(0).pluginList.insertPlugin(plugin,0,nullptr);external->initialiseFully();require(external->getAudioPluginInstance()!=nullptr,"Recovery initial load failed");external->getAudioPluginInstance()->getParameters()[0]->setValueNotifyingHost(0.25f);external->flushPluginStateToValueTree();auto original=external->state.createCopy();auto chunk=original.getProperty("state").toString();require(chunk.isNotEmpty(),"No opaque plugin state");
 external->state.setProperty("filename",dir.getChildFile("Unavailable.vst3").getFullPathName(),nullptr);external->state.setProperty("uniqueId","12345678",nullptr);external->state.setProperty("uid","12345678",nullptr);external->state.setProperty("name","Unavailable Fixture",nullptr);
 s.save();
 auto xml=juce::XmlDocument::parse(s.projectFile);require(xml!=nullptr,"Saved fixture XML missing");
 juce::XmlElement healthy(*xml);
 std::function<void(juce::XmlElement&)> makeMissing=[&](juce::XmlElement& node){if(node.hasTagName("PLUGIN")&&node.getStringAttribute("type")=="vst"){node.setAttribute("filename",dir.getChildFile("Unavailable.vst3").getFullPathName());node.setAttribute("uniqueId","12345678");node.setAttribute("uid","12345678");node.setAttribute("name","Unavailable Fixture");}for(auto* child:node.getChildIterator())makeMissing(*child);};makeMissing(*xml);require(xml->writeTo(s.projectFile),"Missing fixture write failed");plugin=nullptr;s.reopen();auto* missing=s.trackAt(0).pluginList.findFirstPluginOfType<te::ExternalPlugin>();require(missing!=nullptr,"Missing plugin object lost");missing->initialiseFully();require(missing->getAudioPluginInstance()==nullptr,"Missing plugin resolved unexpectedly");require(missing->state.getProperty("state").toString()==chunk,"Opaque state lost on missing load");
 auto output=dir.getChildFile("must-not-export.wav");bool rejected=false;try{s.render(output);}catch(const std::exception&){rejected=true;}require(rejected&&!output.exists(),"Missing plugin export was not rejected before writing");
 s.save();s.reopen();missing=s.trackAt(0).pluginList.findFirstPluginOfType<te::ExternalPlugin>();require(missing&&missing->state.getProperty("state").toString()==chunk,"Missing save lost state");
 for(auto key:{"filename","uniqueId","uid","name"})missing->state.setProperty(key,original.getProperty(key),nullptr);
 require(healthy.writeTo(s.projectFile),"Repair snapshot write failed");s.reopen();auto* restored=s.trackAt(0).pluginList.findFirstPluginOfType<te::ExternalPlugin>();require(restored!=nullptr,"Restored object missing");restored->initialiseFully();require(restored->getAudioPluginInstance()!=nullptr,"Plugin reload failed");require(std::abs(restored->getAudioPluginInstance()->getParameters()[0]->getValue()-0.25f)<1e-7f,"Recovered parameter differs");
 output=dir.getChildFile("recovered.wav");s.render(output);auto audio=readWave(output);require(std::abs(audio.getSample(0,12000)-0.00025f)<1e-7f&&std::abs(audio.getSample(1,24000)+0.0005f)<1e-7f,"Recovered audio differs");
 dir.getChildFile("plugin-recovery-result.json").replaceWithText("{\"checks\":5,\"missing_state_preserved\":true,\"missing_export_rejected\":true,\"parameter_restored\":true,\"device_opened\":false}");
}
